#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Integrate the approved textual transport-interface basis into MMOSON_v7.docx.

This script changes text and summary tables only. It intentionally creates no
schematics, renders, or drawing sheets.
"""
from __future__ import annotations

from copy import deepcopy
from pathlib import Path
import shutil
import sys

from docx import Document

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_DOC = ROOT / "MMOSON_v7.docx"


def set_paragraph_text(paragraph, text: str) -> None:
    first_rpr = None
    if paragraph.runs and paragraph.runs[0]._r.rPr is not None:
        first_rpr = deepcopy(paragraph.runs[0]._r.rPr)
    for run in list(paragraph.runs):
        run._element.getparent().remove(run._element)
    run = paragraph.add_run(text)
    if first_rpr is not None:
        run._r.insert(0, deepcopy(first_rpr))


def replace_prefix(doc, prefix: str, replacement: str) -> None:
    matches = [p for p in doc.paragraphs if p.text.startswith(prefix)]
    if len(matches) != 1:
        raise RuntimeError(f"Expected exactly one paragraph starting with {prefix!r}; found {len(matches)}")
    set_paragraph_text(matches[0], replacement)


def replace_contains_once(doc, needle: str, replacement: str) -> None:
    hits = []
    for p in doc.paragraphs:
        if needle in p.text:
            hits.append(p)
    if len(hits) != 1:
        raise RuntimeError(f"Expected exactly one paragraph containing {needle!r}; found {len(hits)}")
    set_paragraph_text(hits[0], hits[0].text.replace(needle, replacement))


def set_cell(cell, text: str) -> None:
    cell.text = text


def cell_containing(table, needle: str):
    for row in table.rows:
        for cell in row.cells:
            if needle in cell.text:
                return cell
    raise RuntimeError(f"Cell containing {needle!r} not found")


def main(path: Path = DEFAULT_DOC) -> None:
    path = Path(path)
    if not path.exists():
        raise FileNotFoundError(path)

    backup = path.with_name(path.stem + ".pre_transport_v1" + path.suffix)
    if not backup.exists():
        shutil.copy2(path, backup)

    doc = Document(path)

    # 4.7.2 — make the two-corridor topology explicit.
    replace_prefix(doc, "Согласно конструкции станции, каждый цилиндр опирается",
        "Согласно конструкции, каждый цилиндр опирается на два внешних неподвижных рамных узла — передний и задний — через осевую цапфу и подшипниковый корпус. Передняя рама каждого цилиндра является отдельной: она не образует продольного моста между цилиндрами, а пространство между боковыми оболочками вдоль цилиндрических частей остаётся пустым. Передний узел содержит два независимых транспортных коридора — А и Б, каждый в собственной шахте переднего торцевого купола.")
    replace_prefix(doc, "Пассажирские шлюзы передней неподвижной рамы переходят",
        "Пассажирские шлюзы передней неподвижной рамы переходят в герметичные стационарные камеры переднего подшипникового корпуса. Для каждого цилиндра предусмотрены два независимых коридора: А и Б. Каждый коридор имеет два раздельных герметичных канала — восходящий и нисходящий — чистым диаметром 8,0 м. Через многоступенчатый вращающийся гермопереход и полый осевой вал путь входит в переднюю полусферу соответствующего цилиндра; далее коридоры А и Б зеркально расходятся в две наклонные шахты. Межцилиндровых тоннелей нет.")
    replace_prefix(doc, "Резервные причальные места также находятся",
        "Резервные причальные места также находятся на передней раме и являются дублированием основного комплекса. Коридоры А и Б взаимно резервируют друг друга; задняя рама предназначена для антенн, радиаторов, солнечных крыльев и двигательных модулей и не является пассажирским входом.")

    # 4.7.4 — the physical interface and pressure zoning.
    replace_prefix(doc, "Через передний подшипниковый узел проходит не открытый проём",
        "Через передний подшипниковый узел проходит не открытый проём, а герметичный транспортный интерфейс между неподвижной рамой и вращающимся цилиндром. На один цилиндр приходятся два независимых транспортных ствола А и Б; каждый ствол разделён на восходящий и нисходящий канал чистым диаметром 8,0 м. Состав узла включает осевую цапфу, полый транспортный вал, четыре линии шлюзовых камер, вращающуюся герметичную кассету и независимые силовые вводы. Все линии можно изолировать секционными гермодверями до и после вращающегося барьера.")
    replace_prefix(doc, "Опорный узел выполняется как активный магнитный",
        "Опорный узел выполняется как активный магнитный радиально-осевой подшипник с механическими аварийными ловителями. В каждом из четырёх торцевых узлов размещаются два независимых магнитных контура, датчики положения и охлаждаемые силовые модули. Средний диаметр активного кольца — 400 м, осевая активная ширина — 3,0 м. Статор и силовая электроника закреплены на неподвижной раме, роторный пакет мотор-генератора и транспортный роторный модуль — на осевой цапфе. Моторы и подшипники не крепятся к оболочке и не требуют оборудования в межцилиндровом зазоре. Ловители являются аварийной, а не штатной опорой.")
    replace_prefix(doc, "Предварительно принимается диаметр опорного кольца",
        "Предварительно принимается диаметр активного опорного кольца 400 м при ширине 3 м. Два независимых активных пояса имеют по 1,35 м рабочей ширины и разделены сервисной зоной около 0,30 м. Рабочий радиальный зазор принимается 50 мм, осевой — 30 мм до отдельного динамического расчёта. При осевом распоре 10¹⁰ Н среднее расчётное давление кольца составляет около 2,65 МПа. Кольцо находится внутри неподвижного торцевого корпуса и не является наружным ребром цилиндра.")
    replace_prefix(doc, "Герметизация вращающегося стыка и проход транспортной шахты",
        "Герметизация вращающегося стыка и проход транспортных каналов обеспечиваются трёхконтурной системой. Основной барьер — сегментированное вращающееся торцевое уплотнение вокруг роторного транспортного модуля; контрольный барьер — сухой лабиринт с откачиваемой межбарьерной полостью; технический барьер — магнитожидкостные уплотнения вспомогательных валов и приводов. Магнитожидкостное уплотнение не является единственным барьером, удерживающим атмосферу цилиндра.")
    replace_prefix(doc, "Первый барьер — бесконтактное магнитожидкостное",
        "Для каждой из четырёх линий движения принимается последовательность: первая неподвижная камера, вторая неподвижная камера, вращающаяся герметичная кассета, первая вращающаяся приёмная камера, вторая вращающаяся приёмная камера и транспортный канал. Одновременно открывается только одна граница. Каждая линия имеет собственные датчики давления, откачку, продувку и сменную кассету уплотнения. При росте утечки двери по обе стороны вращающегося барьера закрываются автоматически.")
    replace_prefix(doc, "Второй барьер — сухое лабиринтное",
        "Вращающаяся переходная камера не является карданным подвесом. Кабина входит в неё в неподвижном состоянии, камера синхронизируется с угловой скоростью цилиндра на радиусе около 150 м, затем открывается роторная дверь в соответствующий канал. Пол кабины не доворачивается по меняющейся кажущейся вертикали: угол палубы постоянен и равен 10°.")
    replace_prefix(doc, "Транспортное сообщение осуществляется через две последовательно",
        "Транспортное сообщение осуществляется через две последовательно изолируемые камеры до вращающегося барьера и две после него в каждой линии, а не через открытый проём. Два коридора А и Б при этом остаются отдельными маршрутами, а не последовательными камерами. При неисправности участок между камерами отсекается, поэтому потеря одного уплотнения не разгерметизирует цилиндр.")

    # 4.7.5–4.7.6 — cabin transfer, geometry, and capacity.
    replace_prefix(doc, "Это самостоятельная задача, отличная от стыковки.",
        "Это самостоятельная задача, отличная от стыковки. Пассажир прибывает на неподвижный передний причал и проходит карантин, затем одну из четырёх независимых линий коридоров А/Б. После проверки герметичности кабина входит в роторную переходную камеру, которая синхронизируется с угловой скоростью цилиндра на радиусе около 150 м. Через вращающийся гермопереход и полый осевой вал пассажир попадает в защищённый осевой участок передней полусферы, а затем в один из двух зеркальных коридоров — А или Б. В приосевой объём пассажир не выходит.")
    replace_prefix(doc, "Принятое решение — наклонная шахта как основное средство",
        "Принятое решение — два независимых коридора А и Б, каждый в собственной наклонной шахте, как основное средство сообщения; внутри каждого коридора восходящий и нисходящий каналы работают попарно. От переднего интерфейса до точки разделения на r = 150 м идёт защищённый осевой участок около 2 506 м. Далее коридоры зеркально следуют логарифмическим спиралям от r = 150 м до жилой поверхности r = 5 000 м; расчётная длина спиральной части около 4 923 м, суммарный канонический маршрут — 7 429 м, время поездки — 17,8 минуты. Каждая шахта имеет конструкционное устье Ø30 м и два транспортных канала чистым диаметром 8,0 м. Фуникулёрно-эвакуационный рельс размещён в отдельной сервисной зоне и не считается третьим пассажирским коридором.")
    replace_prefix(doc, "Отдельного внимания заслуживает поведение системы",
        "Отдельного внимания заслуживает поведение системы при отказе энергоснабжения. Герметичные двери переходной камеры и секционные двери шахты закрываются от резервного питания. В основном канале центробежный тормоз ограничивает самопроизвольное движение кабины к жилой поверхности; в сервисной зоне сохраняется механический фуникулёрно-эвакуационный рельс. Потеря одного коридора не лишает цилиндр сообщения: второй коридор остаётся работоспособным с пониженной пропускной способностью.")
    replace_prefix(doc, "Расчёт пропускной способности: при парной работе кабин",
        "Расчёт пропускной способности: в каждом коридоре работают два восходящих и два нисходящих состава, то есть две пары кабин на шахту. При кабине на 100 человек и интервале 17,8 минуты один коридор обеспечивает около 675 человек в час. Два коридора переднего торца обеспечивают около 1 350 человек в час на цилиндр; при выводе одного коридора остаётся около 338 человек в час. Порожняя кабина массой 5 т возвращает около 34 кВт·ч на рейс; для полной расчётной массы 15 т энергетический эквивалент составляет около 102 кВт·ч до учёта потерь.")

    # Appendix B.17 — remove the old ambiguity between per-cylinder and station totals.
    replace_prefix(doc, "Решением руководителя проекта от 07.09.2026 число транспортных шахт",
        "Решением руководителя проекта от 07.09.2026 число транспортных шахт сокращено с сорока до двух на каждый цилиндр. Обе шахты каждого цилиндра размещены в толще переднего торцевого купола; всего на станции четыре шахты. Прежняя схема с сорока шахтами, распределёнными по длине цилиндрических частей, отменена.")
    replace_prefix(doc, "Основание решения геометрическое и эксплуатационное.",
        "Основание решения геометрическое и эксплуатационное. Вход на каждый цилиндр единственен: причал вынесен на отдельную неподвижную переднюю раму, за ним расположены карантинный контур, подшипниковый узел и два независимых коридора А и Б. Внутри каждого коридора восходящий и нисходящий каналы разделены физической гермостенкой. Шахта, проложенная в цилиндрической части, начиналась бы в приосевом объёме и требовала бы отдельного пути вдоль оси; принятая схема проводит защищённый осевой участок внутри передней полусферы, после чего разводит два коридора по зеркальным наклонным трассам.")
    replace_prefix(doc, "Длина маршрута пересчитана по меридиану торца-сфероида",
        "Длина маршрута разделена на две конструктивные части. Защищённый осевой участок от вращающегося интерфейса до точки разделения r = 150 м имеет около 2 506 м. Логарифмическая спираль от r = 150 м до r = 5 000 м при θ = 10° имеет около 4 923 м; с учётом округления каноническая длина маршрута составляет 7 429 м. Коридоры А и Б являются зеркальными и имеют одинаковую длину. Точная разница в 1–2 м уточняется после задания координат устьев и не влияет на компоновку.")
    replace_prefix(doc, "Время поездки получено интегрированием закона постоянного наклона",
        "Время поездки по спиральной части получено интегрированием закона постоянного наклона v(r) = ω·r·tg θ / 2 и составляет около 15,2 минуты; оставшееся время до штатных 17,8 минуты приходится на осевой участок, синхронизацию роторной камеры, разгон, торможение и межсекционные ограничения скорости. Скорость у жилой поверхности — 19,5 м/с, у точки разделения — около 0,59 м/с, после чего кабина плавно переходит в роторную приёмную камеру.")
    replace_prefix(doc, "Пропускная способность. При кабине на 100 человек",
        "Пропускная способность. При кабине на 100 человек и двух парах кабин на коридор интервал отправления равен 17,8 минуты, что даёт около 675 человек в час на один коридор и около 1 350 человек в час на один цилиндр. При выводе одного коридора второй сохраняет около 338 человек в час. Заселение 500 000 человек на транспортной пропускной способности занимает около 15,4 суток на один цилиндрический контур или около 31 суток при консервативном учёте одного общего потока; фактический срок всё равно определяется карантином и остаётся около десяти лет.")
    replace_prefix(doc, "Существенно, что это сокращение не является ограничением проекта.",
        "Существенно, что это сокращение не является ограничением проекта. Даже консервативная транспортная оценка ниже санитарной пропускной способности не является узким местом при десятилетнем заселении. Карантинный контур и его 40-суточная выдержка определяют реальную скорость приёма людей, а транспорт обеспечивает резерв и возможность ремонта одного коридора без полной потери сообщения.")
    replace_prefix(doc, "Резервирование. Две шахты обеспечивают взаимное резервирование:",
        "Резервирование. Два коридора каждого цилиндра обеспечивают взаимное резервирование: при выводе одного на обслуживание второй сохраняет около 338 человек в час. В каждом коридоре отдельный механический фуникулёрно-эвакуационный рельс дублирует привод основной кабины; полную независимость от повреждения всей шахты обеспечивают разнесённые коридоры А и Б.")

    # Chapter 12: make the internal network interface explicit.
    replace_prefix(doc, "Сообщение с внешним миром идёт через наклонную шахту",
        "Сообщение с внешним миром идёт через один из двух коридоров — А или Б — в переднем торцевом куполе (п. 4.7.6, Б.17) и является единственным входом в цилиндр; каждый коридор имеет отдельные каналы вверх и вниз, а внутренняя сеть примыкает к их двум жилым вестибюлям пересадочными узлами.")
    replace_prefix(doc, "Передача внутрь цилиндра ведётся от реакторных установок",
        "Передача внутрь цилиндра ведётся от реакторных установок на неподвижной задней раме по двум независимым силовым вводам к неподвижному статору подшипникового узла. Через герметичный вращающийся токопереход или бесконтактную индуктивную муфту питание поступает на внутренние распределительные шины цилиндра; отдельные вводы питают два независимых магнитных контура, мотор-генераторы, датчики, насосы гермоперехода, четыре транспортных канала и их аварийные системы. Предварительная квота энергобаланса на подшипниковые узлы, приводы и силовую электронику — 2 ГВт; источник — реакторная шина, а не солнечные крылья.")

    # 16.6: the textual layout is now resolved, while validations remain open.
    replace_prefix(doc, "Пятое. Детальная компоновка внутренних помещений",
        "Пятое. Детальная компоновка внутренних помещений и точная доля открытого металла жилого объёма остаются нерешёнными. Транспортный интерфейс, передние рамы, два коридора А/Б, четыре канала движения, полый осевой вал и последовательность гермокамер теперь заданы отдельной спецификацией `TRANSPORT_INTERFACE_SPEC_v1.md`, но это ещё не рабочая деталировка помещений.")
    replace_prefix(doc, "Настоящий перечень подлежит пересмотру",
        "Компоновочная база транспортного интерфейса считается закрытой на уровне текстового проектного решения, но следующие проверки остаются обязательными: динамика магнитного подшипника Ø400 м, посадка на механические ловители, МКЭ усиления устьев Ø30 м, ресурс сегментированных уплотнений, тепловое расширение перехода, продольная динамика полной кабины массой 15 т, тормозной путь и радиационная защита закрытой трассы. Настоящий перечень подлежит пересмотру в каждой последующей редакции; закрытые пункты сохраняются с указанием места решения.")

    # Summary tables. Table 47 is the explicit historical comparison.
    table = doc.tables[47]
    set_cell(cell_containing(table, "Стало (2 шахты)"), "Стало (2 коридора / 2 шахты на цилиндр)")
    set_cell(cell_containing(table, "675 чел./ч"), "1 350 чел./ч")
    for row in table.rows:
        if row.cells and row.cells[0].text.strip() == "Устьев Ø30 м в силовом поясе":
            set_cell(row.cells[2], "2 на цилиндр; 4 на станцию")
            break
    else:
        raise RuntimeError("Row 'Устьев Ø30 м в силовом поясе' not found")

    # Keep the numerical summary aligned with the adopted rounded values.
    table39 = doc.tables[39]
    set_cell(cell_containing(table39, "18 мин"), "17,8 мин")
    table38 = doc.tables[38]
    set_cell(cell_containing(table38, "2,7 МПа"), "2,65 МПа")

    doc.save(path)
    print(f"UPDATED {path}")
    print(f"BACKUP  {backup}")


if __name__ == "__main__":
    main(Path(sys.argv[1]) if len(sys.argv) > 1 else DEFAULT_DOC)
